package handlers

import (
	"net/url"
	"os"
	"regexp"
	"strings"
	"testing"
)

// testdata/player_card.html is a card generated by Hararest's buildPlayerHtml.
func TestWithoutHTTPSOnRealCard(t *testing.T) {
	raw, err := os.ReadFile("testdata/player_card.html")
	if err != nil {
		t.Fatal(err)
	}
	card := string(raw)
	if !regexp.MustCompile(`(?i)https`).MatchString(card) {
		t.Fatal("fixture should contain https to be meaningful")
	}
	clean, ok := withoutHTTPS(card)
	if !ok {
		t.Fatalf("http left in card: %q", regexp.MustCompile(`(?i).{0,40}https?.{0,40}`).FindAllString(clean, -1))
	}
	for _, keep := range []string{`"wsUrl":"wss://api.oohara.dev/ws/player/`, "new WebSocket(track.wsUrl)", "function probe(){return Promise.resolve('nonaktif');}", "</script></section>"} {
		if !strings.Contains(clean, keep) {
			t.Errorf("card lost %q", keep)
		}
	}
	// The embedded track JSON must still parse after dropping playerUrl.
	if strings.Contains(clean, `,,`) || strings.Contains(clean, `{,`) {
		t.Error("track JSON left malformed")
	}
}

func TestCardVariants(t *testing.T) {
	ws, _ := url.Parse("wss://api.oohara.dev/ws/player/abc")
	raw, _ := os.ReadFile("testdata/player_card.html")
	card := string(raw)
	variants := cardVariants()
	if len(variants) != 3 {
		t.Fatalf("got %d variants", len(variants))
	}
	if got := variants[0].HTML(card, "T", ws); got != card {
		t.Fatal("control variant changed the payload")
	}
	for _, v := range variants[1:] {
		out := v.HTML(card, "T", ws)
		if out == "" || regexp.MustCompile(`(?i)https?`).MatchString(out) {
			t.Errorf("%s: empty or still contains http", v.Label)
		}
	}
	if doc := variants[2].HTML(card, "T", ws); !strings.HasPrefix(doc, "<!DOCTYPE html>") {
		t.Error("variant 3 is not a full document")
	}
	// Unknown card shape is skipped rather than sent half-cleaned.
	if variants[1].HTML(`<a href="https://x">`, "T", ws) != "" {
		t.Error("unrecognised card was not skipped")
	}
	for _, v := range variants {
		for _, s := range v.Sources(ws) {
			if strings.Contains(s, "/ws/") {
				t.Errorf("%s leaked the session path: %q", v.Label, s)
			}
		}
	}
}
